// Generates docs/card-balance/* (Issue #2). READ-ONLY w.r.t. the game: reads card-data-export/ + engine, writes only markdown/json under docs/card-balance/.
// Every proposal below is PROPOSED / NOT APPROVED. HP and ATK are never changed. Proposed character effects are validated with the real parseEffect.
// Usage: npx tsx scripts/gen-card-balance-docs.ts
import fs from 'node:fs';
import path from 'node:path';
import { parseEffect, type Effect } from '../src/engine/effects';
import { model, tierOf, INCOMING_ATK, DRAW_VALUE, LOOT_VALUE, KILL_DRAW_PROB, COND_HPLOWER_PROB, HORIZON_TURNS } from './card-balance-model';

const ROOT = process.cwd();
const OUT = path.join(ROOT, 'docs/card-balance');
const cards: any[] = JSON.parse(fs.readFileSync(path.join(ROOT, 'card-data-export/cards.json'), 'utf8'));
const verify = JSON.parse(fs.readFileSync(path.join(ROOT, 'docs/card-balance/engine-probe-output.json'), 'utf8'));
fs.mkdirSync(OUT, { recursive: true });

type Row = Record<string, any>;
const parse = (rows: Row[]) => rows.map(r => parseEffect(r as any)).filter((e): e is Effect => !!e);

