// ---------------------------------------------------------------- build ----------------------------------------------------------
const chars = cards.filter(c => c.card_type === 'character');
const meanAp: Record<number, number> = {};
for (const lv of [15, 40, 70]) { const r = chars.filter(c => c.level === lv); meanAp[lv] = r.reduce((a, c) => a + model(lv, { hp: c.hp, atk: c.atk, def: c.def }, parse(c.effects)).ap, 0) / r.length; }

const sig = (c: any) => JSON.stringify(c.effects.map((e: any) => [e.trigger, e.action_text, e.target_text, e.condition_text, e.cost_text, e.use_limit]));
const sameEffect: Record<string, string[]> = {};
for (const c of chars) sameEffect[c.character_id] = chars.filter(o => o !== c && o.level === c.level && sig(o) === sig(c)).map(o => o.character_id);

function roleOf(c: any): string {
  const E = parse(c.effects), k = (f: (e: Effect) => boolean) => E.some(f);
  if (!E.length && c.effects.length) return 'Inactive-ability body';
  if (k(e => e.kind === 'heal')) return c.atk >= 35 ? 'Hybrid attacker/healer' : 'Healer / support';
  if (k(e => e.kind === 'draw' && e.cond === 'target_destroyed')) return 'Thief (draw on kill)';
  if (k(e => e.kind === 'draw')) return 'Card-advantage engine';
  if (k(e => e.kind === 'search_evo')) return 'Evolution tutor';
  if (k(e => e.kind === 'damage')) return 'Chip-damage / removal';
  if (k(e => e.kind === 'protect')) return 'Evasive ninja';
  if (k(e => e.kind === 'atk' && e.trigger === 'on_attack')) return c.atk >= 35 ? 'Frontline attacker' : 'Attacker';
  if (k(e => e.kind === 'atk' && e.trigger === 'passive') || k(e => e.kind === 'maxhp')) return 'Aura leader';
  if (k(e => e.kind === 'atk')) return 'Buffer / ramp';
  return 'Vanilla';
}

interface Out { id: string; name: string; type: string; level: number | null; cls: string; el: string; role: string; cur: Row; prop: Row; changeType: string; engine: string; tierCur: string; tierProp: string; ratioCur: number; ratioProp: number; text: { issue: string; rec: string; reason: string; risk: string }; parts: string[]; same: string[]; notes: string[] }
const outs: Out[] = [];
let parseFail: string[] = [];
for (const c of cards) {
  const id = c.character_id;
  if (c.card_type === 'character') {
    const p = P[id], E = parse(c.effects), m = model(c.level, { hp: c.hp, atk: c.atk, def: c.def }, E);
    const newDef = p?.def ?? c.def;
    const newRows = c.effects.map((r: Row, i: number) => ({ ...r, ...(p?.patch?.[i] ?? {}) }));
    // every row the parser accepted before must still be accepted; patched rows must parse
    c.effects.forEach((r: Row, i: number) => { const before = parseEffect(r as any), after = parseEffect(newRows[i] as any); if (before && !after) parseFail.push(`${id}[${i}]`); if (p?.patch?.[i] && !after) parseFail.push(`${id}[${i}] patched row does not parse`); });
    const m2 = model(c.level, { hp: c.hp, atk: c.atk, def: newDef }, parse(newRows));
    const rc = m.ap / meanAp[c.level], rp = m2.ap / meanAp[c.level];
    const changed = !!p?.patch || (p?.def !== undefined && p.def !== c.def), ct = p?.def !== undefined && p?.patch ? 'def+effect' : p?.def !== undefined ? 'def' : p?.patch ? 'effect' : 'unchanged';
    const notes: string[] = [];
    const inactive = c.effects.filter((r: Row, i: number) => !parseEffect(r as any)).map((r: Row) => r.trigger);
    if (inactive.length) notes.push(`Ability rows not executed by the engine today: ${inactive.join(', ')}.`);
    if (c.level >= 40) notes.push('Reached only through Evolution (cannot be in the main deck).');
    outs.push({ id, name: c.name, type: 'character', level: c.level, cls: c.class, el: c.element, role: roleOf(c), cur: { hp: c.hp, atk: c.atk, def: c.def, effects: c.effects }, prop: { hp: c.hp, atk: c.atk, def: newDef, effects: newRows }, changeType: ct, engine: changed ? (inactive.length && !p?.patch ? 'n/a' : 'supported_by_parser') : 'n/a', tierCur: tierOf(rc), tierProp: tierOf(rp), ratioCur: rc, ratioProp: rp, text: p ?? DEFAULT_NOTE(id, tierOf(rc), rc), parts: m.parts, same: sameEffect[id], notes });
  } else {
    const s = SUPPORT[id];
    outs.push({ id, name: c.name, type: c.card_type, level: null, cls: '-', el: '-', role: s.role, cur: { hp: null, atk: null, def: null, effects: c.effects, rules_text: c.rules_text }, prop: { hp: null, atk: null, def: null, effects: c.effects, rules_text: c.rules_text }, changeType: 'unchanged', engine: s.compat, tierCur: 'n/a', tierProp: 'n/a', ratioCur: 0, ratioProp: 0, text: { issue: s.issue, rec: s.rec, reason: s.reason, risk: s.risk }, parts: [], same: [], notes: s.engineProp ? [`Linked engine proposals: ${s.engineProp.join(', ')}`] : [] });
  }
}

// ---------------------------------------------------------------- integrity checks (fail the generator) ----------------------------------------------------------
const problems: string[] = [];
if (outs.length !== 70) problems.push(`expected 70 cards, got ${outs.length}`);
if (new Set(outs.map(o => o.id)).size !== 70) problems.push('duplicate ids');
for (const o of outs) { if (o.cur.hp !== o.prop.hp || o.cur.atk !== o.prop.atk) problems.push(`HP/ATK changed for ${o.id}`); }
for (const id of Object.keys(P)) if (!outs.find(o => o.id === id)) problems.push(`proposal for unknown card ${id}`);
problems.push(...parseFail);
if (problems.length) { console.error('INTEGRITY FAILED:\n' + problems.join('\n')); process.exit(1); }

